<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Outbox\Infrastructure\Driven;

use Exception;
use Override;
use PHPMailer\PHPMailer\PHPMailer;
use PHPMailer\PHPMailer\SMTP;
use Civi\Lughauth\Features\Notification\Outbox\Domain\Gateway\SmtpMailSenderGateway;
use Civi\Lughauth\Features\Notification\Outbox\Domain\Model\OutboundMail;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Security\AesCypherService;

/**
 * Adapts SmtpMailSenderGateway to PHPMailer.
 *
 * send()           — uses global SMTP settings from AppConfig (same source as MailSenderAdapter).
 * sendWithConfig() — uses a tenant-specific SmtpOutboundConfig, decrypting the stored password
 *                    via AesCypherService. Port is derived from isUseTls(): 465 (TLS) or 587.
 */
class SmtpMailSenderAdapter implements SmtpMailSenderGateway
{
    public function __construct(
        private readonly AppConfig $config,
        private readonly AesCypherService $cypher,
    ) {
    }

    #[Override]
    public function send(OutboundMail $mail): void
    {
        $mailer = $this->buildBaseMailer();

        $mailer->Host     = $this->config->get('mailer.host', 'localhost');
        $mailer->Port     = (int) $this->config->get('mailer.port', '587');
        $mailer->Username = $this->config->get('mailer.username', '');
        $mailer->Password = $this->config->get('mailer.password', '');

        if ($this->config->get('mailer.start.tls', 'none') === 'REQUIRED') {
            $mailer->SMTPSecure = PHPMailer::ENCRYPTION_STARTTLS;
        }

        if ($this->config->get('mailer.auth.methods', '') !== '') {
            $mailer->SMTPAuth = true;
        }

        $mailer->setFrom(
            $this->config->get('mailer.from.email', 'info@localhost'),
            $this->config->get('mailer.from.name', 'info'),
        );

        $this->applyMailContent($mailer, $mail);
        $this->doSend($mailer);
    }

    #[Override]
    public function sendWithConfig(SmtpOutboundConfig $config, OutboundMail $mail): void
    {
        $mailer = $this->buildBaseMailer();

        $mailer->Host     = $config->getHost();
        $mailer->Port     = $config->isUseTls() ? 465 : 587;
        $mailer->Username = $config->getLogin();
        $mailer->Password = $config->getPlainPassword($this->cypher);
        $mailer->SMTPAuth = true;

        if ($config->isUseTls()) {
            $mailer->SMTPSecure = PHPMailer::ENCRYPTION_STARTTLS;
        }

        if (null !== $config->getTimeout()) {
            $mailer->Timeout = $config->getTimeout();
        }

        $mailer->setFrom(
            $config->getSenderEmail(),
            $config->getSenderName() ?? '',
        );

        $this->applyMailContent($mailer, $mail);
        $this->doSend($mailer);
    }

    // ---------------------------------------------------------------------------
    // Private helpers
    // ---------------------------------------------------------------------------

    private function buildBaseMailer(): PHPMailer
    {
        $mailer = new PHPMailer();
        $mailer->isSMTP();
        $mailer->SMTPDebug = SMTP::DEBUG_OFF;
        return $mailer;
    }

    private function applyMailContent(PHPMailer $mailer, OutboundMail $mail): void
    {
        $mailer->Subject = $mail->subject();
        $mailer->addAddress($mail->recipient());

        $mailer->isHTML(true);
        $mailer->Body    = $mail->htmlContent();
        $mailer->AltBody = $mail->textContent() ?? strip_tags($mail->htmlContent());
    }

    private function doSend(PHPMailer $mailer): void
    {
        ob_start();
        $result = $mailer->send();
        $trace  = ob_get_clean();

        if (!$result) {
            throw new Exception($mailer->ErrorInfo . ($trace ? ': ' . $trace : ''));
        }
    }
}
